static V fwp_p_gpu_run(V src, V nv, V consts, V inputs) {
    (void)src; (void)nv; (void)consts; (void)inputs;
    V s = fwp_cstr("no OpenCL device: OpenCL is not available on this target");
    return fwp_data(1, 1, &s);
}

